def circular_shift(x, shift):
    x_str = str(x)
    num_digits = len(x_str)

    if shift > num_digits:
        return x_str[::-1]

    actual_shift = shift % num_digits
    if actual_shift == 0:
        return x_str

    if shift > 0:
        result = x_str[-actual_shift:] + x_str[:-actual_shift]
    else:
        result = x_str[actual_shift:] + x_str[:actual_shift]

